self.addEventListener('install', (e) => {
  // cache: 'reload' skips the HTTP cache, so unhashed files (art/*.jpg) are never a stale copy from an older build.
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES.map((f) => new Request(f, { cache: 'reload' })))).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('sweet-stack-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  // ?seed=, ?level= and the like still get the cached page; any page load gets index.html.
  const hit = req.mode === 'navigate' ? caches.match('./index.html', { cacheName: CACHE }) : caches.match(req, { cacheName: CACHE, ignoreSearch: true });
  e.respondWith(hit.then((r) => r || fetch(req)));
});
